mapper.select:
SELECT t.*, e.emp_no, e.name AS employee_name, d.name AS dept_name FROM hr_tax_deduction t JOIN hr_employee e ON e.id = t.employee_id LEFT JOIN sys_dept d ON d.id = e.dept_id
(e.emp_no LIKE CONCAT('%', #{keyword}, '%') OR e.name LIKE CONCAT('%', #{keyword}, '%')) AND t.type = #{type} AND t.employee_id = #{employeeId}
ORDER BY e.emp_no, t.type, t.start_period
